(* A tank fill valve control program.
   Inputs: LowFloat (0=Low, 1=High), HighFloat (0=Low, 1=High)
   Outputs: FillValve (0=Off, 1=On)
   Logic: Fill valve opens when LowFloat is ON. Closes when HighFloat is ON.
   Uses a TON timer to track the duration of the fill phase. *)

PROGRAM TankValveControl
VAR
    LowFloat AT %I0.0 : BOOL;
    HighFloat AT %I0.1 : BOOL;
    FillValve AT %Q0.0 : BOOL;
    FillTimer AT %Q0.1 : TON;
    LastPhase : INT := 0;
END_VAR

(* Initialize the timer to 0 seconds *)
FillTimer(IN := 0, PT := T#0s);
LastPhase := 0;

(* Main Control Loop *)
(* Check if the valve should be ON or OFF based on current inputs *)
FillValve := (LowFloat = 1) AND (HighFloat = 0);

(* If the valve is ON, start the timer to close it after a set duration *)
IF FillValve THEN
    FillTimer(IN := 1, PT := T#10s);
END_IF;

(* Handle Phase Transitions *)
(* If the valve is OFF and the LowFloat switch turns ON, start filling *)
IF NOT FillValve AND LowFloat = 1 THEN
    FillTimer(IN := 1, PT := T#10s);
END_IF;

(* If the valve is ON and the HighFloat switch turns ON, stop filling *)
IF FillValve AND HighFloat = 1 THEN
    FillTimer(IN := 0, PT := T#0s);
END_IF;

END_PROGRAM
>>>

